-- A parenthesized identity option list honors `START WITH n` — the sequence seeds
-- to `n - 1`, so the first two auto-assigned rows are 100 and 101. (The other
-- options — INCREMENT/MINVALUE/… — are pglet-ignored, matching its flat-counter
-- sequence model.)
-- @setup
CREATE TABLE t (id int GENERATED BY DEFAULT AS IDENTITY (START WITH 100), name text);
INSERT INTO t (name) VALUES ('a'), ('b');
-- @test
SELECT id, name FROM t ORDER BY id;
